mapper.select:
select t.* from (select hfp.funding_plan_id,hfp.funding_plan_number,hfp.status,pp.project_id,pp.ref_project_id, (SELECT meaning from sys_code_value_b_v where code = 'HLS.WFL_FUNDING_STATUS' and code_value = hfp.status) status_n, (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id=cc.tenant_id) as bp_name, cc.contract_id,cc.contract_number as payment_number, pp.contract_number as contract_number, pp.contract_name as contract_name, pp.project_number as project_number, pp.project_name as project_name, pp.host_project_manager, (select s.description from sys_user s where s.user_id = pp.host_project_manager) PROJECT_MANAGER, pp.host_unit_id, (select fou.unit_name from fnd_org_unit fou where fou.unit_id = pp.host_unit_id) UNIT_MANAGER,
pp.assist_project_manager, (select s.description from sys_user s where s.user_id = pp.assist_project_manager) assist_project_manager_n, pp.assist_unit_id, (select fou.unit_name from fnd_org_unit fou where fou.unit_id = pp.assist_unit_id) assist_unit_name,
(SELECT ppcn.credit_period_from FROM prj_project_credit_notice ppcn where ppcn.project_id = pp.ref_project_id and ppcn.prj_notice_id = (SELECT max(ppcn.prj_notice_id) FROM prj_project_credit_notice ppcn where ppcn.project_id = pp.ref_project_id and ppcn.notice_create_date is not null)) as credit_period_from, (SELECT ppcn.credit_period_to FROM prj_project_credit_notice ppcn where ppcn.project_id = pp.ref_project_id and ppcn.prj_notice_id = (SELECT max(ppcn.prj_notice_id) FROM prj_project_credit_notice ppcn where ppcn.project_id = pp.ref_project_id and ppcn.notice_create_date is not null)) as credit_period_to, hfp.PROPOSED_LAUNCH_DATE, hfp.LOAN_TOTAL_AMOUNT, hfp.LOAN_NET_AMOUNT FROM CON_contract cc,prj_project pp ,HLS_FUNDING_PLAN hfp where pp.project_id = cc.project_id and hfp.contract_id = cc.contract_id) t
1=1
AND t.funding_plan_id = #{fundingPlanId}
AND t.project_id = #{projectId}
AND t.bp_name like concat(concat('%',#{bpName}),'%')
AND t.project_name like concat(concat('%',#{projectName}),'%')
AND t.contract_number like concat(concat('%',#{contractNumber}),'%')
AND t.contract_name like concat(concat('%',#{contractName}),'%')
AND t.status = #{status}
and t.proposed_launch_date >= #{loanTimeFrom}
and Ct.proposed_launch_date <= #{loanTimeTo}

select hfp.*
  from hls_funding_plan hfp

    hfp.contract_id = #{contractId}
